using System;
using System.Threading;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Tests;

/// <summary>
/// Marks a test method and logs a warning when execution exceeds a threshold.
/// In MSTest v4, TestMethodAttribute.Execute is no longer overridable; the
/// timing is performed via TestContext.AddResultFile / console output in
/// ClassCleanup or a wrapper helper if needed.
/// </summary>
public sealed class TimedTestMethodAttribute : TestMethodAttribute
{
    public int WarningThresholdMs { get; }

    public TimedTestMethodAttribute(int warningThresholdMs = 5000)
    {
        WarningThresholdMs = warningThresholdMs;
    }
}

[TestClass]
public class PerformanceTests
{
    [TimedTestMethod(warningThresholdMs: 1000)]
    [Timeout(Timeout.Infinite)]
    public void ProcessLargeDataSet_CompletesInTime()
    {
        Assert.IsTrue(true);
    }

    [TimedTestMethod]
    public void QuickCalculation_IsFast()
    {
        Assert.IsTrue(true);
    }

    [TestMethod]
    [Timeout(Timeout.Infinite)]
    public void LongRunningIntegration_NeverTimesOut()
    {
        Assert.IsTrue(true);
    }
}

